"use client"

import * as React from "react"
import { Command as CommandPrimitive } from "cmdk"
import * as DialogPrimitive from "@radix-ui/react-dialog"

import { cn } from "@/lib/utils"
import { Scrollbar } from "@/components/ui/scrollbar"

const SearchContext = React.createContext("")
const SearchSetter = React.createContext<(search: string) => void>(() => {})

// A row matches when the words you typed sit inside its value or keywords.
// ponytail: substring, not cmdk's fuzzy score, so the highlighter can mark exactly what matched.
const contains = (value: string, search: string, keywords?: string[]) =>
  [value, ...(keywords ?? [])].join(" ").toLowerCase().includes(search.trim().toLowerCase()) ? 1 : 0

/** The highlighter: wraps each place the query appears in <mark>. */
function marks(text: string, q: string): React.ReactNode {
  if (!q) return text
  const lower = text.toLowerCase()
  const out: React.ReactNode[] = []
  let at = 0
  for (let i = lower.indexOf(q); i >= 0; i = lower.indexOf(q, at)) {
    if (i > at) out.push(text.slice(at, i))
    out.push(<mark key={i}>{text.slice(i, i + q.length)}</mark>)
    at = i + q.length
  }
  out.push(text.slice(at))
  return out
}

/** The name split at its first match: what comes before, then the key (the match onward). The mesostic sets the key on its axis; elsewhere the two run on. */
function marked(text: string, query: string): React.ReactNode {
  const q = query.trim().toLowerCase()
  const at = Math.max(q ? text.toLowerCase().indexOf(q) : 0, 0)
  return (
    <>
      <span className="db-command-before">{text.slice(0, at)}</span>
      <span className="db-command-key">{marks(text.slice(at), q)}</span>
    </>
  )
}

type CommandProps = React.ComponentProps<typeof CommandPrimitive> & {
  /** headline: what you type set large, rows below. mesostic: every row set on one axis at its match. index: each group run on as a book's index. */
  variant?: "headline" | "mesostic" | "index"
  /** What the input holds when it opens, for a palette that starts from a query. */
  defaultSearch?: string
}

/** A command palette. What you type is set large and italic; matches are marked; the chosen row steps forward. */
function Command({ className, filter = contains, variant = "headline", defaultSearch = "", ...props }: CommandProps) {
  const [search, setSearch] = React.useState(defaultSearch)
  return (
    <SearchContext.Provider value={search}>
      <SearchSetter.Provider value={setSearch}>
        <CommandPrimitive data-slot="command" data-variant={variant} filter={filter} className={cn("db-command", className)} {...props} />
      </SearchSetter.Provider>
    </SearchContext.Provider>
  )
}
/** What you type is yours, so it is italic and as large as a headline. Give it a placeholder that names what to type. */
function CommandInput({ className, onValueChange, ...props }: React.ComponentProps<typeof CommandPrimitive.Input>) {
  const search = React.useContext(SearchContext)
  const setSearch = React.useContext(SearchSetter)
  return (
    <CommandPrimitive.Input
      data-slot="command-input"
      aria-label={props["aria-label"] ?? props.placeholder}
      value={search}
      onValueChange={(next) => {
        setSearch(next)
        onValueChange?.(next)
      }}
      className={cn("db-command-input", className)}
      {...props}
    />
  )
}

/** The rows, on the scrollbar's rail when there are more than fit. */
function CommandList({ className, children, ...props }: React.ComponentProps<typeof CommandPrimitive.List>) {
  return (
    <CommandPrimitive.List data-slot="command-list" className={cn("db-command-list", className)} {...props}>
      {children}
      <Scrollbar />
    </CommandPrimitive.List>
  )
}

/** Empty copy names something to try. */
function CommandEmpty({ className, children, ...props }: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  const search = React.useContext(SearchContext)
  return (
    <CommandPrimitive.Empty data-slot="command-empty" className={cn("db-command-empty", className)} {...props}>
      {children ?? <>Nothing matches “{search}”.</>}
    </CommandPrimitive.Empty>
  )
}

function CommandGroup({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.Group>) {
  return <CommandPrimitive.Group data-slot="command-group" className={cn("db-command-group", className)} {...props} />
}

function CommandSeparator({ className, ...props }: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return <CommandPrimitive.Separator data-slot="command-separator" className={cn("db-command-separator", className)} {...props} />
}

/** A row. Words in it are set as the name and marked where they match; other parts (CommandHint, CommandShortcut) sit at the end. */
function CommandItem({ className, children, ...props }: React.ComponentProps<typeof CommandPrimitive.Item>) {
  const search = React.useContext(SearchContext)
  return (
    <CommandPrimitive.Item data-slot="command-item" className={cn("db-command-option", className)} {...props}>
      {React.Children.map(children, (child) =>
        typeof child === "string" ? <span className="db-command-name">{marked(child, search)}</span> : child,
      )}
    </CommandPrimitive.Item>
  )
}

/** A key that runs the row, drawn as a cap (base db-kbd). */
function CommandShortcut({ className, ...props }: React.ComponentProps<"kbd">) {
  return <kbd data-slot="command-shortcut" className={cn("db-kbd", className)} {...props} />
}

/** A quiet word at the end of a row, when it isn't a key: a year, a kind. */
function CommandHint({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="command-hint" className={cn("db-command-hint", className)} {...props} />
}

type CommandDialogProps = CommandProps & {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Read out by screen readers; not shown. */
  title?: string
}

/** The ⌘K palette: a modal over the page. Register the key yourself; this only opens where you tell it. */
function CommandDialog({ open, onOpenChange, title = "Search", children, ...props }: CommandDialogProps) {
  return (
    <DialogPrimitive.Root open={open} onOpenChange={onOpenChange}>
      <DialogPrimitive.Portal>
        <DialogPrimitive.Overlay data-slot="command-overlay" className="db-command-overlay" />
        <DialogPrimitive.Content data-slot="command-dialog" aria-describedby={undefined} className="db-command-dialog db-corners">
          <DialogPrimitive.Title className="db-sr">{title}</DialogPrimitive.Title>
          <Command {...props}>{children}</Command>
        </DialogPrimitive.Content>
      </DialogPrimitive.Portal>
    </DialogPrimitive.Root>
  )
}

export {
  Command,
  CommandDialog,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandSeparator,
  CommandShortcut,
  CommandHint,
  type CommandProps,
  type CommandDialogProps,
}

@layer components {
  /* ── db-command ── what you type is set as large as a headline.
     cmdk marks the chosen row aria-selected; rows it filters out are removed, so a
     row that comes back arrives again. The dialog is Radix's: an overlay like the
     dialog's backdrop, and a frame that opens out from inside. */
  .db-command { display: grid; gap: var(--db-space-4); }
  .db-command-input {
    appearance: none; width: 100%; margin: 0; border: 0; border-radius: 0; outline: 0; padding: 0 0 0.12em;
    background: linear-gradient(var(--db-rule-strong), var(--db-rule-strong)) no-repeat 0 100% / 100% var(--db-hairline);
    color: var(--db-ink); font-family: var(--db-expression); font-style: italic; font-weight: 400; text-overflow: ellipsis;
    font-size: calc(var(--db-f) * var(--db-expression-scale)); line-height: 1.15;
  }
  .db-command-input::placeholder { font-family: var(--db-voice); font-style: normal; font-weight: 200; font-size: var(--db-f); color: var(--db-pencil); opacity: 1; }
  .db-command-input:focus-visible { background-image: linear-gradient(var(--db-accent), var(--db-accent)); background-size: 100% var(--db-stroke); }
  .db-command-list { max-height: 22rem; overflow: auto; padding-inline-end: var(--db-space-4); } /* the rows stop short of the scrollbar's rail */
  .db-command-group [cmdk-group-heading] { margin-block: var(--db-space-4) var(--db-space-1); margin-inline: 0; font-size: var(--db-pp); line-height: var(--db-pp-lh); color: var(--db-pencil); }
  .db-command-separator { height: var(--db-hairline); margin-block: var(--db-space-3); background: var(--db-rule); }
  .db-command-option {
    display: grid; grid-template-columns: minmax(0, 1fr); grid-auto-flow: column; grid-auto-columns: auto; align-items: baseline; column-gap: var(--db-space-4);
    --step: 8px; padding-block: 0.4em; border-block-end: var(--db-hairline) solid var(--db-rule); cursor: pointer; color: var(--db-graphite);
    animation: db-arrive var(--db-moderato) var(--db-exhale) backwards; animation-delay: calc(min(sibling-index(), 9) * var(--db-arpeggio));
  }
  .db-command-option::after { content: "→" / ""; inline-size: 1.2em; justify-self: end; color: var(--db-ink); opacity: 0; translate: calc(-1 * var(--step)) 0; transition: translate var(--db-moderato) var(--db-exhale), opacity var(--db-allegro); }
  :is([dir="rtl"], [dir="rtl"] *) .db-command-option { --step: -8px; }
  :is([dir="rtl"], [dir="rtl"] *) .db-command-option::after { content: "←" / ""; }
  .db-command-option > * { transition: translate var(--db-moderato) var(--db-exhale), opacity var(--db-allegro), color var(--db-allegro); }
  .db-command-name { font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-command-hint { font-size: var(--db-pp); color: var(--db-pencil); }
  .db-command-option:hover, .db-command-option[aria-selected="true"] { color: var(--db-ink); }
  .db-command-option[aria-selected="true"] .db-command-name { translate: var(--step) 0; }
  .db-command-option[aria-selected="true"]::after { opacity: 1; translate: 0 0; }
  .db-command-option[aria-disabled="true"] { cursor: not-allowed; opacity: 0.5; }
  .db-command-option mark { padding: 0; margin: 0; } /* part of a word: no overshoot, or it would crowd the letters either side */
  .db-command-empty { padding-block: var(--db-space-4); font-size: var(--db-mp); color: var(--db-graphite); }

  /* ── mesostic ── John Cage's mesostics, the printed concordance: every row is set on one vertical axis at the place
     your words appear. The found letters stand on the axis in roman capitals, the rest of the name falls away either side,
     and what you type sits on the same axis above them, so the query reads straight down through the results.
     The axis is the middle of the rows less the arrow's column; the input's text starts there too. */
  .db-command[data-variant="mesostic"] { --axis-tail: var(--db-space-6); }
  .db-command[data-variant="mesostic"] .db-command-input { padding-inline-start: calc(50% - (var(--db-space-4) + var(--axis-tail)) / 2); }
  .db-command[data-variant="mesostic"] :is([cmdk-group-heading], .db-command-empty) { padding-inline-start: calc(50% - var(--axis-tail) / 2); }
  .db-command[data-variant="mesostic"] .db-command-option { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr) var(--axis-tail); grid-auto-flow: row; column-gap: 0; }
  .db-command[data-variant="mesostic"] .db-command-name { display: contents; }
  .db-command[data-variant="mesostic"] .db-command-before { grid-area: 1 / 1; justify-self: end; min-width: 0; max-width: 100%; overflow: hidden; white-space: pre; font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-command[data-variant="mesostic"] .db-command-key { grid-area: 1 / 2; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: pre; font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-command[data-variant="mesostic"] .db-command-option > :not(.db-command-name) { grid-area: 1 / 1; justify-self: start; }
  .db-command[data-variant="mesostic"] .db-command-option::after { grid-area: 1 / 3; }
  .db-command[data-variant="mesostic"] mark { background: none; color: inherit; margin: 0; }
  .db-command[data-variant="mesostic"] .db-command-key > mark:first-child { color: var(--db-ink); font-weight: 600; text-transform: uppercase; }
  .db-command[data-variant="mesostic"] .db-command-option:is(:hover, [aria-selected="true"]) :is(.db-command-before, .db-command-key) { color: var(--db-ink); }
  @media (max-width: 40rem) {
    .db-command[data-variant="mesostic"] { --axis-tail: var(--db-space-5); }
    .db-command[data-variant="mesostic"] .db-command-option > :not(.db-command-name) { grid-area: 2 / 2; }
  }

  /* ── index ── a book's index, run in: each group's name hangs in the margin as the headword, and its rows run on after it
     as one paragraph, sub-entries parted by semicolons and closed with a full stop. A match is marked; the chosen entry is
     underlined in ink. Rows that stop matching leave the sentence, which closes up. */
  .db-command[data-variant="index"] .db-command-group { display: grid; grid-template-columns: minmax(0, 7rem) minmax(0, 1fr); column-gap: var(--db-space-5); align-items: baseline; margin-block-start: var(--db-space-4); }
  .db-command[data-variant="index"] .db-command-group [cmdk-group-heading] { margin: 0; }
  .db-command[data-variant="index"] .db-command-group [cmdk-group-items] { font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-command[data-variant="index"] .db-command-option { display: inline; padding: 0; border: 0; animation-name: db-command-fade; }
  .db-command[data-variant="index"] .db-command-option > * { margin-inline-start: 0.3em; }
  .db-command[data-variant="index"] .db-command-option > .db-command-name { margin: 0; text-decoration: underline var(--db-hairline) transparent; text-underline-offset: 0.2em; transition: text-decoration-color var(--db-allegro), color var(--db-allegro); }
  .db-command[data-variant="index"] .db-command-option::after { content: ";\00a0" / ""; inline-size: auto; opacity: 1; translate: none; color: var(--db-pencil); }
  .db-command[data-variant="index"] .db-command-option:last-child::after { content: "." / ""; }
  .db-command[data-variant="index"] .db-command-option:is(:hover, [aria-selected="true"]) > .db-command-name { translate: none; text-decoration-color: currentColor; }
  .db-command[data-variant="index"] .db-command-separator { display: none; }
  @media (max-width: 40rem) {
    .db-command[data-variant="index"] .db-command-group { grid-template-columns: minmax(0, 1fr); row-gap: var(--db-space-1); }
  }

  /* The ⌘K dialog. */
  .db-command-overlay {
    position: fixed; inset: 0; z-index: 50;
    background: color-mix(in srgb, var(--db-paper) 86%, transparent);
    -webkit-backdrop-filter: blur(6px); backdrop-filter: blur(6px);
    animation: db-command-fade var(--db-andante);
  }
  .db-command-overlay[data-state="closed"] { animation: db-command-fade var(--db-andante) reverse forwards; }
  .db-command-dialog {
    position: fixed; z-index: 51; inset-inline: 0; inset-block-start: 12vh; margin-inline: auto;
    width: min(44rem, calc(100vw - 2 * var(--db-margin))); padding: var(--db-space-7);
    background: var(--db-paper); color: var(--db-graphite);
    --db-corner: 14px;
    animation: db-command-in var(--db-andante) var(--db-exhale);
  }
  .db-command-dialog[data-state="closed"] { animation: db-command-out var(--db-allegro) var(--db-breath) forwards; }
  .db-command-dialog[data-state="open"]::after { animation: db-command-frame var(--db-andante) var(--db-exhale) 80ms backwards; }
  .db-command-dialog .db-command-list { max-height: min(28rem, 50vh); }
  @media (max-width: 40rem) {
    .db-command-dialog { padding: var(--db-space-6) var(--db-space-5); }
    .db-command-input { font-size: calc(var(--db-mf) * var(--db-expression-scale)); }
    .db-command-input::placeholder { font-size: var(--db-mf); }
  }
  @keyframes db-command-fade { from { opacity: 0; } }
  @keyframes db-command-in { from { opacity: 0; translate: 0 12px; } }
  @keyframes db-command-out { to { opacity: 0; } }
  @keyframes db-command-frame { from { opacity: 0; scale: 0.95; } }
}
